@Test
public void testBasic() {
    ClientOpts opts = new ClientOpts();
    String[] args = new String[] { "-u", "userabc", "-o", "instance.name=myinst", "-o", "instance.zookeepers=zoo1,zoo2", "-o", "auth.type=password", "-o", "auth.principal=user123", "-o", "auth.token=mypass" };
    opts.parseArgs("test", args);
    Properties props = opts.getClientProps();
    assertEquals("user123", ClientProperty.AUTH_PRINCIPAL.getValue(props));
    assertTrue(opts.getToken() instanceof PasswordToken);
    assertEquals("myinst", props.getProperty("instance.name"));
    opts = new ClientOpts();
    args = new String[] { "-o", "instance.name=myinst", "-o", "instance.zookeepers=zoo1,zoo2", "-o", "auth.type=password", "-o", "auth.token=mypass", "-u", "userabc" };
    opts.parseArgs("test", args);
    props = opts.getClientProps();
    assertEquals("userabc", ClientProperty.AUTH_PRINCIPAL.getValue(props));
    assertTrue(opts.getToken() instanceof PasswordToken);
    assertEquals("myinst", props.getProperty("instance.name"));
}

@Test
public void testPassword() {
    ClientOpts opts = new ClientOpts();
    String[] args = new String[] { "--password", "mypass", "-u", "userabc", "-o", "instance.name=myinst", "-o", "instance.zookeepers=zoo1,zoo2", "-o", "auth.principal=user123" };
    opts.parseArgs("test", args);
    Properties props = opts.getClientProps();
    assertEquals("user123", ClientProperty.AUTH_PRINCIPAL.getValue(props));
    assertTrue(opts.getToken() instanceof PasswordToken);
    assertTrue(opts.getToken().equals(new PasswordToken("mypass")));
    assertEquals("myinst", props.getProperty("instance.name"));
}

