    for (int i = 3; i < 10; i++) {
        scanner.fetchColumnFamily(new Text(colStr(i)));
    }
    assertEquals(defaultData, toMap(scanner));
    scanner.clearColumns();
    assertEquals(createTestData(10, 10, 10), toMap(scanner));
