    expected.put("f1", 4L);
    expected.put("f2", 2L);
    expected.put("f3", 2L);
    expected.put("f4", 1L);
    expected.put("f5", 1L);
    assertEquals(expected, csum.getCounters());
}

@Test
public void testMerge() {
    SummarizerConfiguration sc = SummarizerConfiguration.builder(VisibilitySummarizer.class).addOption(MAX_COUNTERS_OPT, "5").build();
