@Test
public void test1() {
    Text colf = new Text("a");
    Text colq = new Text("b");
    Value dvOld = new Value("old");
    Value dvDel = new Value("old");
    Value dvNew = new Value("new");
    TreeMap<Key, Value> tm = new TreeMap<>();
    Key k;
    for (int i = 0; i < 2; i++) {
        for (long j = 0; j < 5; j++) {
            k = new Key(new Text(String.format("%03d", i)), colf, colq, j);
            tm.put(k, dvOld);
        }
    }
    k = new Key(new Text(String.format("%03d", 0)), colf, colq, 5);
    k.setDeleted(true);
    tm.put(k, dvDel);
    for (int i = 0; i < 2; i++) {
        for (long j = 6; j < 11; j++) {
            k = new Key(new Text(String.format("%03d", i)), colf, colq, j);
            tm.put(k, dvNew);
        }
    }
    assertEquals("Initial size was " + tm.size(), 21, tm.size());
    Text checkRow = new Text("000");
    try {
        SortedKeyValueIterator<Key, Value> it = DeletingIterator.wrap(new SortedMapIterator(tm), false, Behavior.PROCESS);
        it.seek(new Range(), EMPTY_COL_FAMS, false);
        TreeMap<Key, Value> tmOut = new TreeMap<>();
        while (it.hasTop()) {
            tmOut.put(it.getTopKey(), it.getTopValue());
            it.next();
        }
        assertEquals("size after no propagation was " + tmOut.size(), 15, tmOut.size());
        for (Entry<Key, Value> e : tmOut.entrySet()) {
            if (e.getKey().getRow().equals(checkRow)) {
                byte[] b = e.getValue().get();
                assertEquals('n', b[0]);
                assertEquals('e', b[1]);
                assertEquals('w', b[2]);
            }
        }
    } catch (IOException e) {
        fail();
    }
    try {
        SortedKeyValueIterator<Key, Value> it = DeletingIterator.wrap(new SortedMapIterator(tm), true, Behavior.PROCESS);
        it.seek(new Range(), EMPTY_COL_FAMS, false);
        TreeMap<Key, Value> tmOut = new TreeMap<>();
        while (it.hasTop()) {
            tmOut.put(it.getTopKey(), it.getTopValue());
            it.next();
        }
        assertEquals("size after propagation was " + tmOut.size(), 16, tmOut.size());
        for (Entry<Key, Value> e : tmOut.entrySet()) {
            if (e.getKey().getRow().equals(checkRow)) {
                byte[] b = e.getValue().get();
                if (e.getKey().isDeleted()) {
                    assertEquals('o', b[0]);
                    assertEquals('l', b[1]);
                    assertEquals('d', b[2]);
                } else {
                    assertEquals('n', b[0]);
                    assertEquals('e', b[1]);
                    assertEquals('w', b[2]);
                }
            }
        }
    } catch (IOException e) {
        fail();
    }
}

