    for (int i = 0; i < partitioned.length; i++) {
        partitioned.set(i, new ArrayList<>());
    }
    p1.partition(mutations, partitioned);
    m1 = new Mutation("r1");
    m1.put("cf1", "cq1", "v1");
    m2 = new Mutation("r2");
    m2.put("cf1", "cq1", "v2");
    m2.put("cf2", "cq2", "v3");
    m3 = new Mutation("r3");
    m3.put("cf1", "cq1", "v4");
    m4 = new Mutation("r4");
    m4.put("cf1", "cq1", "v6");
    assertEquals(toKeySet(m1, m2, m3, m4), toKeySet(partitioned.get(0)));
    m3 = new Mutation("r3");
    m3.put("cf3", "cq2", "v5");
    m4 = new Mutation("r4");
    m4.put("cf3", "cq2", "v7");
    assertEquals(toKeySet(m3, m4), toKeySet(partitioned.get(1)));
    m4 = new Mutation("r4");
    m4.put("cf5", "cq3", "v8");
    assertEquals(toKeySet(m4, m5), toKeySet(partitioned.get(2)));
