@Test
public void testCorrectRangeInputSplits() throws Exception {
    Job job = Job.getInstance();
    String table = getUniqueNames(1)[0];
    Authorizations auths = new Authorizations("foo");
    Collection<IteratorSetting.Column> fetchColumns = Collections.singleton(new IteratorSetting.Column(new Text("foo"), new Text("bar")));
    Collection<Pair<Text, Text>> fetchColumnsText = Collections.singleton(new Pair<>(new Text("foo"), new Text("bar")));
    client.tableOperations().create(table);
    InputFormatOptions<Job> opts = AccumuloInputFormat.configure().clientProperties(getClientInfo().getProperties()).table(table).auths(auths);
    opts.fetchColumns(fetchColumns).scanIsolation(true).localIterators(true).store(job);
    AccumuloInputFormat aif = new AccumuloInputFormat();
    List<InputSplit> splits = aif.getSplits(job);
    assertEquals(1, splits.size());
    InputSplit split = splits.get(0);
    assertEquals(RangeInputSplit.class, split.getClass());
    RangeInputSplit risplit = (RangeInputSplit) split;
    assertEquals(table, risplit.getTableName());
    assertEquals(true, risplit.isIsolatedScan());
    assertEquals(true, risplit.usesLocalIterators());
    assertEquals(fetchColumnsText, risplit.getFetchedColumns());
}

