@Test
public void testTooManyTablets() throws Exception {
    Map<KeyExtent, String> loadRanges = new HashMap<>();
    loadRanges.put(nke(null, "c"), "f1 f2");
    loadRanges.put(nke("c", "g"), "f2 f3");
    loadRanges.put(nke("g", "r"), "f2 f4");
    loadRanges.put(nke("r", "w"), "f2 f5");
    loadRanges.put(nke("w", null), "f2 f6");
    List<String> requiredRows = Arrays.asList("c", "g", "r", "w");
    for (Set<String> otherRows : Sets.powerSet(Set.of("a", "e", "i", "s", "x"))) {
        var tablets = Iterables.concat(requiredRows, otherRows);
        for (int maxTablets = 3; maxTablets < 10; maxTablets++) {
            int totalTablets = requiredRows.size() + otherRows.size() + 1;
            if (totalTablets > maxTablets) {
                runTooManyTest(loadRanges, tablets, "{f2=" + totalTablets + "}", maxTablets);
            } else {
                runTest(loadRanges, createExtents(tablets), maxTablets);
            }
        }
        runTest(loadRanges, createExtents(tablets), 0);
    }
    loadRanges.clear();
    loadRanges.put(nke("ca", "cz"), "f3");
    loadRanges.put(nke("ma", "mm"), "f3");
    loadRanges.put(nke("re", "rz"), "f4");
    runTooManyTest(loadRanges, Arrays.asList("ca", "cd", "cz", "e", "ma", "md", "mm", "re", "rz"), "{f3=4}", 3);
    runTooManyTest(loadRanges, Arrays.asList("b", "ca", "cd", "cz", "e", "ma", "md", "mm", "re", "rz"), "{f3=4}", 3);
    runTooManyTest(loadRanges, Arrays.asList("ca", "cd", "cz", "e", "ma", "md", "mm", "re", "rf", "rh", "rm", "rz"), "{f3=4, f4=4}", 3);
    runTooManyTest(loadRanges, Arrays.asList("ca", "cd", "cz", "e", "ma", "mm", "re", "rf", "rh", "rm", "rz"), "{f4=4}", 3);
}

@Test
public void testSingleShutdown() throws Exception {
    final TServerInstance tserver = EasyMock.createMock(TServerInstance.class);
    final boolean force = false;
    final ShutdownTServer op = new ShutdownTServer(tserver, force);
    final Master master = EasyMock.createMock(Master.class);
    final long tid = 1L;
    final TServerConnection tserverCnxn = EasyMock.createMock(TServerConnection.class);
    final TabletServerStatus status = new TabletServerStatus();
    status.tableMap = new HashMap<>();
    // Put in a table info record, don't care what
    status.tableMap.put("a_table", new TableInfo());
    master.shutdownTServer(tserver);
    EasyMock.expectLastCall().once();
    EasyMock.expect(master.onlineTabletServers()).andReturn(Collections.singleton(tserver));
    EasyMock.expect(master.getConnection(tserver)).andReturn(tserverCnxn);
    EasyMock.expect(tserverCnxn.getTableMap(false)).andReturn(status);
    EasyMock.replay(tserver, tserverCnxn, master);
    // FATE op is not ready
    long wait = op.isReady(tid, master);
    assertTrue("Expected wait to be greater than 0", wait > 0);
    EasyMock.verify(tserver, tserverCnxn, master);
    // Reset the mocks
    EasyMock.reset(tserver, tserverCnxn, master);
    // reset the table map to the empty set to simulate all tablets unloaded
    status.tableMap = new HashMap<>();
    master.shutdownTServer(tserver);
    EasyMock.expectLastCall().once();
    EasyMock.expect(master.onlineTabletServers()).andReturn(Collections.singleton(tserver));
    EasyMock.expect(master.getConnection(tserver)).andReturn(tserverCnxn);
    EasyMock.expect(tserverCnxn.getTableMap(false)).andReturn(status);
    EasyMock.expect(master.getMasterLock()).andReturn(null);
    tserverCnxn.halt(null);
    EasyMock.expectLastCall().once();
    EasyMock.replay(tserver, tserverCnxn, master);
    // FATE op is not ready
    wait = op.isReady(tid, master);
    assertTrue("Expected wait to be 0", wait == 0);
    Repo<Master> op2 = op.call(tid, master);
    assertNull("Expected no follow on step", op2);
    EasyMock.verify(tserver, tserverCnxn, master);
}

