@Test
public void testAlphaNumRegex() {
    Pattern p = Pattern.compile(ParameterValidator.ALPHA_NUM_REGEX);
    assertTrue(p.matcher("asdlkfj234kj324").matches());
    assertFalse(p.matcher("234-324").matches());
    assertFalse(p.matcher("").matches());
    p = Pattern.compile(ParameterValidator.ALPHA_NUM_REGEX_BLANK_OK);
    assertTrue(p.matcher("asdlkfj234kj324").matches());
    assertTrue(p.matcher("").matches());
    assertFalse(p.matcher("234-324").matches());
}

@Test
public void testServerRegex() {
    Pattern p = Pattern.compile(ParameterValidator.HOSTNAME_PORT_REGEX);
    assertTrue("Did not match hostname with dots", p.matcher("ab3cd.12d34.3xyz.net:12").matches());
    assertTrue("Did not match hostname with dash", p.matcher("abcd.123.server-foo.com:56789").matches());
    assertTrue("Did not match hostname and port", p.matcher("abcd.123.server-foo.com:1234").matches());
    assertTrue("Did not match all numeric and port", p.matcher("127.0.0.1:9999").matches());
    assertTrue("Did not match all numeric and port", p.matcher("ServerName:9999").matches());
    assertFalse("Port number required", p.matcher("127.0.0.1").matches());
    assertFalse(p.matcher("abcd.1234.*.xyz").matches());
    assertFalse(p.matcher("abcd.1234.;xyz").matches());
    assertFalse(p.matcher("abcd.12{3}4.xyz").matches());
    assertFalse(p.matcher("abcd.12[3]4.xyz").matches());
    assertFalse(p.matcher("abcd=4.xyz").matches());
    assertFalse(p.matcher("abcd=\"4.xyz\"").matches());
    assertFalse(p.matcher("abcd\"4.xyz\"").matches());
}

@Test
public void zkHostSortingTest() {
    List<String> expectedHosts = Arrays.asList("rack1node1", "rack2node1", "rack4node1", "rack4node4");
    // Add the states in a not correctly sorted order
    TreeSet<ZooKeeperState> states = new TreeSet<>();
    states.add(new ZooKeeperState("rack4node4", "leader", 10));
    states.add(new ZooKeeperState("rack4node1", "follower", 10));
    states.add(new ZooKeeperState("rack1node1", "follower", 10));
    states.add(new ZooKeeperState("rack2node1", "follower", 10));
    List<String> actualHosts = new ArrayList<>(4);
    for (ZooKeeperState state : states) {
        actualHosts.add(state.keeper);
    }
    // Assert we have 4 of each
    assertEquals(expectedHosts.size(), actualHosts.size());
    // Assert the ordering is correct
    for (int i = 0; i < expectedHosts.size(); i++) {
        assertEquals(expectedHosts.get(i), actualHosts.get(i));
    }
}

