    KeyValue[] entries1 = { createKeyValue(DEFINE_TABLET, 100, 10, extent), createKeyValue(MUTATION, 100, 10, m1), createKeyValue(COMPACTION_FINISH, 102, 10, null), createKeyValue(MUTATION, 105, 10, m2) };
    Arrays.sort(entries1);
    Map<String, KeyValue[]> logs = new TreeMap<>();
    logs.put("entries1", entries1);
    var e = assertThrows(IllegalStateException.class, () -> recover(logs, extent));
    assertTrue(e.getMessage().contains("not " + LogEvents.OPEN));
}

