@Test
public void test1() throws Exception {
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        client.tableOperations().create(tableName);
        try (BatchWriter bw = client.createBatchWriter(tableName)) {
            bw.addMutation(nm(new byte[] { 0 }));
            bw.addMutation(nm(new byte[] { 0, 0 }));
            bw.addMutation(nm(new byte[] { 0, 1 }));
            bw.addMutation(nm(new byte[] { 0, 1, 0 }));
            bw.addMutation(nm(new byte[] { 1, 0 }));
            bw.addMutation(nm(new byte[] { 'a', 'b', 'c' }));
            bw.addMutation(nm(new byte[] { (byte) 0xff }));
            bw.addMutation(nm(new byte[] { (byte) 0xff, (byte) 0xff, (byte) 0xff, (byte) 0xff, (byte) 0xff, (byte) 0xff }));
            for (int i = 0; i < 1000; i += 5) {
                bw.addMutation(nm(String.format("r%05d", i)));
            }
        }
        try (Scanner scanner = client.createScanner(tableName, Authorizations.EMPTY)) {
            ArrayList<Text> rows = new ArrayList<>();
            for (Entry<Key, Value> entry : scanner) {
                rows.add(entry.getKey().getRow());
            }
            for (int i = rows.size() - 1; i > 0; i--) {
                Text max = client.tableOperations().getMaxRow(tableName, Authorizations.EMPTY, null, true, rows.get(i), false);
                assertEquals(rows.get(i - 1), max);
                max = client.tableOperations().getMaxRow(tableName, Authorizations.EMPTY, rows.get(i - 1), true, rows.get(i), false);
                assertEquals(rows.get(i - 1), max);
                max = client.tableOperations().getMaxRow(tableName, Authorizations.EMPTY, rows.get(i - 1), false, rows.get(i), false);
                assertNull(max);
                max = client.tableOperations().getMaxRow(tableName, Authorizations.EMPTY, null, true, rows.get(i), true);
                assertEquals(rows.get(i), max);
                max = client.tableOperations().getMaxRow(tableName, Authorizations.EMPTY, rows.get(i), true, rows.get(i), true);
                assertEquals(rows.get(i), max);
                max = client.tableOperations().getMaxRow(tableName, Authorizations.EMPTY, rows.get(i - 1), false, rows.get(i), true);
                assertEquals(rows.get(i), max);
            }
            Text max = client.tableOperations().getMaxRow(tableName, Authorizations.EMPTY, null, true, null, true);
            assertEquals(rows.get(rows.size() - 1), max);
            max = client.tableOperations().getMaxRow(tableName, Authorizations.EMPTY, null, true, new Text(new byte[] { 0 }), false);
            assertNull(max);
            max = client.tableOperations().getMaxRow(tableName, Authorizations.EMPTY, null, true, new Text(new byte[] { 0 }), true);
            assertEquals(rows.get(0), max);
        }
    }
}

