@Test
public void testInvalidDelete() throws Exception {
    killMacGc();
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        String table = getUniqueNames(1)[0];
        c.tableOperations().create(table);
        try (BatchWriter bw = c.createBatchWriter(table)) {
            Mutation m1 = new Mutation("r1");
            m1.put("cf1", "cq1", "v1");
            bw.addMutation(m1);
        }
        c.tableOperations().flush(table, null, null, true);
        // ensure an invalid delete entry does not cause GC to go berserk ACCUMULO-2520
        c.securityOperations().grantTablePermission(c.whoami(), MetadataTable.NAME, TablePermission.WRITE);
        try (BatchWriter bw = c.createBatchWriter(MetadataTable.NAME)) {
            bw.addMutation(createDelMutation("", "", "", ""));
            bw.addMutation(createDelMutation("", "testDel", "test", "valueTest"));
            // path is invalid but value is expected - only way the invalid entry will come through
            // processing and
            // show up to produce error in output to allow while loop to end
            bw.addMutation(createDelMutation("/", "", "", SkewedKeyValue.STR_NAME));
        }
        ProcessInfo gc = cluster.exec(SimpleGarbageCollector.class);
        try {
            String output = "";
            while (!output.contains("Ignoring invalid deletion candidate")) {
                sleepUninterruptibly(250, TimeUnit.MILLISECONDS);
                try {
                    output = gc.readStdOut();
                } catch (UncheckedIOException ioe) {
                    log.error("Could not read all from cluster.", ioe);
                }
            }
        } finally {
            gc.getProcess().destroy();
        }
        try (Scanner scanner = c.createScanner(table, Authorizations.EMPTY)) {
            Iterator<Entry<Key, Value>> iter = scanner.iterator();
            assertTrue(iter.hasNext());
            Entry<Key, Value> entry = iter.next();
            assertEquals("r1", entry.getKey().getRow().toString());
            assertEquals("cf1", entry.getKey().getColumnFamily().toString());
            assertEquals("cq1", entry.getKey().getColumnQualifier().toString());
            assertEquals("v1", entry.getValue().toString());
            assertFalse(iter.hasNext());
        }
    }
}

@Test
public void testProperPortAdvertisement() throws Exception {
    try (AccumuloClient client = Accumulo.newClient().from(getClientProperties()).build()) {
        ZooReaderWriter zk = new ZooReaderWriter(cluster.getZooKeepers(), 30000, OUR_SECRET);
        String path = ZooUtil.getRoot(client.instanceOperations().getInstanceID()) + Constants.ZGC_LOCK;
        for (int i = 0; i < 5; i++) {
            List<String> locks;
            try {
                locks = zk.getChildren(path);
            } catch (NoNodeException e) {
                Thread.sleep(5000);
                continue;
            }
            if (locks != null && !locks.isEmpty()) {
                Collections.sort(locks);
                String lockPath = path + "/" + locks.get(0);
                String gcLoc = new String(zk.getData(lockPath));
                assertTrue("Found unexpected data in zookeeper for GC location: " + gcLoc, gcLoc.startsWith(Service.GC_CLIENT.name()));
                int loc = gcLoc.indexOf(ServerServices.SEPARATOR_CHAR);
                assertNotEquals("Could not find split point of GC location for: " + gcLoc, -1, loc);
                String addr = gcLoc.substring(loc + 1);
                int addrSplit = addr.indexOf(':');
                assertNotEquals("Could not find split of GC host:port for: " + addr, -1, addrSplit);
                String host = addr.substring(0, addrSplit), port = addr.substring(addrSplit + 1);
                // We shouldn't have the "bindall" address in zk
                assertNotEquals("0.0.0.0", host);
                // Nor should we have the "random port" in zk
                assertNotEquals(0, Integer.parseInt(port));
                return;
            }
            Thread.sleep(5000);
        }
        fail("Could not find advertised GC address");
    }
}

@Test
public void gcMetricsPublished() {
    boolean gcMetricsEnabled = cluster.getSiteConfiguration().getBoolean(Property.GC_METRICS_ENABLED);
    if (!gcMetricsEnabled) {
        log.info("gc metrics are disabled with GC_METRICS_ENABLED=true");
        return;
    }
    // log.trace("Client started, properties:{}", accumuloClient.properties());
    log.trace("Client started, properties:{}", accumuloClient.properties());
    MetricsFileTailer gcTail = new MetricsFileTailer("accumulo.sink.file-gc");
    Thread t1 = new Thread(gcTail);
    t1.start();
    // uncomment for manual jmx / jconsole validation - not for automated testing
    // manualValidationPause();
    try {
        var updateTimestamp = System.currentTimeMillis();
        // Get next update after current time
        LineUpdate firstUpdate = waitForUpdate(updateTimestamp, gcTail);
        Map<String, Long> firstSeenMap = parseLine(firstUpdate.getLine());
        log.trace("L:{}", firstUpdate.getLine());
        log.trace("M:{}", firstSeenMap);
        assertTrue(lookForExpectedKeys(firstSeenMap));
        sanity(updateTimestamp, firstSeenMap);
        // Get next update after the first one
        updateTimestamp = firstUpdate.getLastUpdate();
        LineUpdate nextUpdate = waitForUpdate(updateTimestamp, gcTail);
        Map<String, Long> updateSeenMap = parseLine(nextUpdate.getLine());
        log.debug("Line received:{}", nextUpdate.getLine());
        log.trace("Mapped values:{}", updateSeenMap);
        assertTrue(lookForExpectedKeys(updateSeenMap));
        sanity(updateTimestamp, updateSeenMap);
        validate(firstSeenMap, updateSeenMap);
    } catch (Exception ex) {
        log.debug("reads", ex);
    }
}

