@Test
public void compactionMetrics() throws AccumuloSecurityException, AccumuloException {
    assumeTrue(accumuloClient.instanceOperations().getSystemConfiguration().get(Property.MASTER_FATE_METRICS_ENABLED.getKey()).compareTo("true") == 0);
    MetricsFileTailer.LineUpdate firstUpdate = metricsTail.waitForUpdate(-1, NUM_TAIL_ATTEMPTS, TAIL_DELAY);
    List<SlowOps> tables = new ArrayList<>();
    for (int i = 0; i < tableCount; i++) {
