    for (int i = start; i <= end; i++) {
        nm.put(newKey(i), newValue(i));
    }
    long mem2 = nm.getMemoryUsed();
    if (mem1 != mem2) {
        throw new RuntimeException("Memory changed after inserting duplicate data " + mem1 + " " + mem2);
    }
    for (int i = start; i <= end; i++) {
        nm.put(newKey(i), newValue(i));
    }
    long mem3 = nm.getMemoryUsed();
    if (mem1 != mem3) {
