    // modify map after iter created
    nm.put(newKey(2), newValue(2));
    assertTrue(iter.hasTop());
    assertEquals(iter.getTopKey(), newKey(0));
    iter.next();
    assertTrue(iter.hasTop());
    assertEquals(iter.getTopKey(), newKey(1));
