@Test
public void localityGroupChange() throws Exception {
    // Make changes to locality groups and ensure nothing is lost
    try (AccumuloClient accumuloClient = Accumulo.newClient().from(getClientProps()).build()) {
        String table = getUniqueNames(1)[0];
        TableOperations to = accumuloClient.tableOperations();
        to.create(table);
        String[] config = { "lg1:colf", null, "lg1:colf,xyz", "lg1:colf,xyz;lg2:c1,c2" };
        int i = 0;
        for (String cfg : config) {
            to.setLocalityGroups(table, getGroups(cfg));
            ingest(accumuloClient, getClientInfo(), ROWS * (i + 1), 1, 50, ROWS * i, table);
            to.flush(table, null, null, true);
            verify(accumuloClient, getClientInfo(), 0, 1, 50, ROWS * (i + 1), table);
            i++;
        }
        to.delete(table);
        to.create(table);
        config = new String[] { "lg1:colf", null, "lg1:colf,xyz", "lg1:colf;lg2:colf" };
        i = 1;
        for (String cfg : config) {
            ingest(accumuloClient, getClientInfo(), ROWS * i, 1, 50, 0, table);
            ingest(accumuloClient, getClientInfo(), ROWS * i, 1, 50, 0, "xyz", table);
            to.setLocalityGroups(table, getGroups(cfg));
            to.flush(table, null, null, true);
            verify(accumuloClient, getClientInfo(), ROWS * i, 1, 50, 0, table);
            verify(accumuloClient, getClientInfo(), ROWS * i, 1, 50, 0, "xyz", table);
            i++;
        }
    }
}

@Test
public void replaceMissingRFile() throws Exception {
    log.info("Ingest some data, verify it was stored properly, replace an" + " underlying rfile with an empty one and verify we can scan.");
    Properties props = getClientProperties();
    ClientInfo info = ClientInfo.from(props);
    try (AccumuloClient client = Accumulo.newClient().from(props).build()) {
        String tableName = getUniqueNames(1)[0];
        ReadWriteIT.ingest(client, info, ROWS, COLS, 50, 0, tableName);
        ReadWriteIT.verify(client, info, ROWS, COLS, 50, 0, tableName);
        client.tableOperations().flush(tableName, null, null, true);
        client.tableOperations().offline(tableName, true);
        log.debug("Replacing rfile(s) with empty");
        try (Scanner meta = client.createScanner(MetadataTable.NAME, Authorizations.EMPTY)) {
            String tableId = client.tableOperations().tableIdMap().get(tableName);
            meta.setRange(new Range(new Text(tableId + ";"), new Text(tableId + "<")));
            meta.fetchColumnFamily(DataFileColumnFamily.NAME);
            boolean foundFile = false;
            for (Entry<Key, Value> entry : meta) {
                foundFile = true;
                Path rfile = new Path(entry.getKey().getColumnQualifier().toString());
                log.debug("Removing rfile '{}'", rfile);
                cluster.getFileSystem().delete(rfile, false);
                Process processInfo = cluster.exec(CreateEmpty.class, rfile.toString()).getProcess();
                assertEquals(0, processInfo.waitFor());
            }
            assertTrue(foundFile);
        }
        log.trace("invalidate cached file handles by issuing a compaction");
        client.tableOperations().online(tableName, true);
        client.tableOperations().compact(tableName, null, null, false, true);
        log.debug("make sure we can still scan");
        try (Scanner scan = client.createScanner(tableName, Authorizations.EMPTY)) {
            scan.setRange(new Range());
            long cells = 0L;
            for (Entry<Key, Value> entry : scan) {
                if (entry != null)
                    cells++;
            }
            assertEquals(0L, cells);
        }
    }
}

@Test
public void testBalancing() throws Exception {
    try (AccumuloClient client = Accumulo.newClient().from(getClientProperties()).build()) {
        String tablename = getUniqueNames(1)[0];
        SortedSet<Text> splits = new TreeSet<>();
        splits.add(new Text("01a"));
        splits.add(new Text("01m"));
        splits.add(new Text("01z"));
        splits.add(new Text("02a"));
        splits.add(new Text("02f"));
        splits.add(new Text("02r"));
        splits.add(new Text("02z"));
        splits.add(new Text("03a"));
        splits.add(new Text("03f"));
        splits.add(new Text("03m"));
        splits.add(new Text("03r"));
        HashMap<String, String> props = new HashMap<>();
        props.put(RegexGroupBalancer.REGEX_PROPERTY, "(\\d\\d).*");
        props.put(RegexGroupBalancer.DEFAUT_GROUP_PROPERTY, "03");
        props.put(RegexGroupBalancer.WAIT_TIME_PROPERTY, "50ms");
        props.put(Property.TABLE_LOAD_BALANCER.getKey(), RegexGroupBalancer.class.getName());
        client.tableOperations().create(tablename, new NewTableConfiguration().setProperties(props).withSplits(splits));
        while (true) {
            Thread.sleep(250);
            Table<String, String, MutableInt> groupLocationCounts = getCounts(client, tablename);
            boolean allGood = true;
            allGood &= checkGroup(groupLocationCounts, "01", 1, 1, 3);
            allGood &= checkGroup(groupLocationCounts, "02", 1, 1, 4);
            allGood &= checkGroup(groupLocationCounts, "03", 1, 2, 4);
            allGood &= checkTabletsPerTserver(groupLocationCounts, 3, 3, 4);
            if (allGood) {
                break;
            }
        }
        splits.clear();
        splits.add(new Text("01b"));
        splits.add(new Text("01f"));
        splits.add(new Text("01l"));
        splits.add(new Text("01r"));
        client.tableOperations().addSplits(tablename, splits);
        while (true) {
            Thread.sleep(250);
            Table<String, String, MutableInt> groupLocationCounts = getCounts(client, tablename);
            boolean allGood = true;
            allGood &= checkGroup(groupLocationCounts, "01", 1, 2, 4);
            allGood &= checkGroup(groupLocationCounts, "02", 1, 1, 4);
            allGood &= checkGroup(groupLocationCounts, "03", 1, 2, 4);
            allGood &= checkTabletsPerTserver(groupLocationCounts, 4, 4, 4);
            if (allGood) {
                break;
            }
        }
        // merge group 01 down to one tablet
        client.tableOperations().merge(tablename, null, new Text("01z"));
        while (true) {
            Thread.sleep(250);
            Table<String, String, MutableInt> groupLocationCounts = getCounts(client, tablename);
            boolean allGood = true;
            allGood &= checkGroup(groupLocationCounts, "01", 1, 1, 1);
            allGood &= checkGroup(groupLocationCounts, "02", 1, 1, 4);
            allGood &= checkGroup(groupLocationCounts, "03", 1, 2, 4);
            allGood &= checkTabletsPerTserver(groupLocationCounts, 2, 3, 4);
            if (allGood) {
                break;
            }
        }
    }
}

