        assertContains(ret, tservers, Map.of(r1, Set.of(t1)), Map.of(t1, Set.of(r1)));
        ranges.add(r2);
        ret = client.tableOperations().locate(tableName, ranges);
        assertContains(ret, tservers, Map.of(r1, Set.of(t1), r2, Set.of(t1)), Map.of(t1, Set.of(r1, r2)));
        TreeSet<Text> splits = new TreeSet<>();
        splits.add(new Text("r"));
        client.tableOperations().addSplits(tableName, splits);
        ret = client.tableOperations().locate(tableName, ranges);
        assertContains(ret, tservers, Map.of(r1, Set.of(t2), r2, Set.of(t2, t3)), Map.of(t2, Set.of(r1, r2), t3, Set.of(r2)));
        client.tableOperations().offline(tableName, true);
        try {
            client.tableOperations().locate(tableName, ranges);
            fail();
        } catch (TableOfflineException e) {
            // expected
        }
        client.tableOperations().delete(tableName);
        try {
            client.tableOperations().locate(tableName, ranges);
            fail();
        } catch (TableNotFoundException e) {
            // expected
        }
    }
}

